cat > /tmp/test_normal.R << 'EOF'
source('/app/ars.R')

# Test normal distribution only
cat("\n=== NORMAL DISTRIBUTION TEST ===\n")
set.seed(123)
n_samples <- 1000

tryCatch({
  samples <- ars(n_samples, dnorm, mean=0, sd=1)

  if (length(samples) == n_samples) {
    sample_mean <- mean(samples)
    sample_sd <- sd(samples)
    cat(sprintf("Generated %d samples\n", length(samples)))
    cat(sprintf("Sample mean: %.4f (expected 0.0000)\n", sample_mean))
    cat(sprintf("Sample SD: %.4f (expected 1.0000)\n", sample_sd))

    # Save samples to file
    writeLines(as.character(samples), "/app/normal_samples.txt")
    cat("Samples saved to /app/normal_samples.txt\n")

    if (abs(sample_mean - 0) < 0.1 && abs(sample_sd - 1) < 0.1) {
      cat("TEST_NORMAL_DISTRIBUTION: PASS\n")
    } else {
      cat("TEST_NORMAL_DISTRIBUTION: FAIL (statistics out of range)\n")
    }
  } else {
    cat(sprintf("TEST_NORMAL_DISTRIBUTION: FAIL - Only generated %d samples\n", length(samples)))
  }
}, error = function(e) {
  cat(sprintf("TEST_NORMAL_DISTRIBUTION: FAIL\n"))
  cat(sprintf("Error: %s\n", e$message))
})
EOF

Rscript /tmp/test_normal.R 2>&1 | tail -20

